import{_ as r,C as o,o as n,c as l,j as t,a,E as d,ag as c}from"./chunks/framework.HG0H2VLS.js";const y=JSON.parse('{"title":"StepsTable","description":"","frontmatter":{},"headers":[],"relativePath":"cc-patterns/steps-table.md","filePath":"cc-patterns/steps-table.md"}'),h={name:"cc-patterns/steps-table.md"},p={id:"stepstable",tabindex:"-1"};function b(g,e,u,m,f,_){const s=o("Badge"),i=o("ComponentDemo");return n(),l("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-stepstable",tabindex:"-1"},[a("title: StepsTable "),t("a",{class:"header-anchor",href:"#title-stepstable","aria-label":'Permalink to "title: StepsTable"'},"​")],-1)),t("h1",p,[e[0]||(e[0]=a("StepsTable ",-1)),d(s,{type:"info",text:"Design System"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#stepstable","aria-label":'Permalink to "StepsTable <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"Article steps list on Datatables: Show details (every row) × Width; StepRow / StepDetail / toolbar / footer")],-1)),d(i,{src:"/demos/src/cc/patterns/StepsTable/StepsTable.html"}),e[6]||(e[6]=c('<h2 id="token-gaps-decisions" tabindex="-1">Token Gaps &amp; Decisions <a class="header-anchor" href="#token-gaps-decisions" aria-label="Permalink to &quot;Token Gaps &amp; Decisions&quot;">​</a></h2><p>Built on Datatables — no new table. Column widths follow the table resizing rule (Title fills, others hug); Figma&#39;s fixed pixel columns are a Figma-table limitation (designer). Live tick in Figma is <code>green/11</code> from the Radix Full library → <code>--ai-text-success</code> (identical #218358). No Edit Columns on Steps (designer). Draft detail row bg was borrowed <code>--ai-btn-secondary-bg-hover</code> → <code>--ai-datatable-table-expanded-bg</code>. Tab count says 8 while the table says 21 — draft inconsistency, flagged.</p><h2 id="contextual-override-—-author-chip-border-designer-2026-09-28" tabindex="-1">Contextual override — author chip border (designer, 2026-09-28) <a class="header-anchor" href="#contextual-override-—-author-chip-border-designer-2026-09-28" aria-label="Permalink to &quot;Contextual override — author chip border (designer, 2026-09-28)&quot;">​</a></h2><p>The &quot;Created By&quot; chip is <code>btn btn--tertiary btn--sm</code> + <code>.steps-table__author-chip</code>, which holds <code>--ai-border-secondary</code> through rest / hover / focus — the same Case B line as the listing rows&#39; account chip (<code>.datatables__account-chip</code>). In Figma both StepRow variants&#39; <code>Created By</code> instances (<code>3881:4873</code>, <code>3881:4920</code>) carry a 1px inside stroke bound to <code>border/secondary</code>; the Button set itself is unchanged (tertiary border tokens stay transparent).</p><h2 id="on-the-listing-engine-—-full-parity-designer-2026-09-29" tabindex="-1">On the listing engine — full parity (designer, 2026-09-29) <a class="header-anchor" href="#on-the-listing-engine-—-full-parity-designer-2026-09-29" aria-label="Permalink to &quot;On the listing engine — full parity (designer, 2026-09-29)&quot;">​</a></h2><p>The Steps table is now a <strong>listing screen</strong>: <code>LISTING_SCREENS[&#39;article-steps&#39;]</code> (<code>RecordScreen/listing-data-article-steps.js</code>, generated by <code>_generate.py</code> from <code>steps_data.py</code>) run by <code>ListingScreen.js</code>. The datatable markup is lifted from <code>ListingScreen/Articles.html</code> at build time (<code>record_markup.listing_datatable()</code>), so it cannot drift from the listings. It gains, for free: the adaptive column fit, <strong>Edit Columns</strong> (show/hide + drag-reorder), <strong>Settings</strong> (Expanding row / Horizontal scroll), the kebab detail, paging, and per-user persistence.</p><ul><li><strong>One detail row, two separate triggers</strong> (designer correction, 2026-09-29): the <strong>kebab</strong> reveals ONLY that row&#39;s columns that did not fit (or the listing&#39;s &quot;Every column is showing at this width&quot; note); <strong>Show details</strong> reveals ONLY the step body (engine hook <code>config.rowDetail</code> → <code>.datatables__detail-extra</code>), on every row. Both on → both halves. The first build let the kebab open the step body too — wrong: each half is now gated by its own trigger in StepsTable.css.</li><li><strong>Horizontal scroll:</strong> kebab hidden (listing rule), Show details still works; the step body pins to the visible width (the cell inset moves inside the block; the scroll pass re-spans the cell).</li><li>Checkboxes kept with <code>selectable: true</code> — the step bulk actions are not designed yet.</li><li>Columns (priority order): Order · Title (fluid, link) · Type · Float · Design frame · Lookup (<code>flag</code> cells: ✓ / –) · Created by (account chip) · Publish start · Live (flag) · edit · kebab. <code>identityColumns: 2</code> (Order + Title always show).</li><li>Fixed on the way: with Show details on, <code>.steps-table--details .datatables__row-detail</code> beat Datatables&#39; <code>--measuring</code> hide, so the open detail cells inflated every measured column (a 2,477px scroll table for ~1,200px of columns). A higher-specificity measuring rule restores it.</li><li><strong>Figma:</strong> StepsToolbar <code>3881:4747</code> now has an <code>Actions</code> group (gap <code>spacing/3</code>): Show details + Button Secondary <strong>base</strong> &quot;Edit Columns&quot; (Icon/Columns3) + &quot;Settings&quot; (Icon/24px/Settings). Base matches the code&#39;s 40px Edit Columns — the Listings page frames still draw it at <code>sm</code> (32px).</li><li>Verified headless: 20 of 21 rows, 12 cols at 1600 / 9 at 1280, Show details opens 20 rows with the step body, scroll mode 11 cols (1,208px table), step body pinned at full scroll, no errors; Articles and Media Items listings unchanged.</li></ul><h2 id="mobile-designer-amend-2026-09-30" tabindex="-1">Mobile (designer amend, 2026-09-30) <a class="header-anchor" href="#mobile-designer-amend-2026-09-30" aria-label="Permalink to &quot;Mobile (designer amend, 2026-09-30)&quot;">​</a></h2><p><code>@container cs-page (max-width: 767px)</code>: the &quot;Show details&quot; label (<code>.steps-table__details-toggle</code>) is <code>--ai-font-fixed-2xs</code> (desktop <code>xs</code>).</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Variant</th><th>Notes</th></tr></thead><tbody><tr><td><code>3881:7518</code></td><td>Details=Off, Width=Standard</td><td></td></tr><tr><td><code>3881:7518</code></td><td>Details=On, Width=Standard</td><td>every row expanded</td></tr><tr><td><code>3881:7518</code></td><td>Details=Off, Width=Full</td><td></td></tr><tr><td><code>3881:7518</code></td><td>Details=On, Width=Full</td><td></td></tr><tr><td><code>3881:4979</code></td><td>StepRow State=Default / Expanded</td><td></td></tr><tr><td><code>3881:4747</code></td><td>StepsToolbar</td><td></td></tr><tr><td><code>3881:4768</code></td><td>StepsHeaderRow</td><td></td></tr><tr><td><code>3881:4808</code></td><td>StepDetail</td><td></td></tr><tr><td><code>3881:4980</code></td><td>StepsFooter</td><td></td></tr></tbody></table><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>Table</td><td><code>.datatables.steps-table (+ --details, --full) [data-steps-table]</code></td></tr><tr><td>Toolbar</td><td><code>.datatables__toolbar / __meta / __select + .steps-table__details-toggle (Toggle xxs [data-steps-details])</code></td></tr><tr><td>Header / sort</td><td><code>.datatables__sort (+ --active)</code></td></tr><tr><td>Row</td><td><code>.datatables__row; title .steps-table__title-cell &gt; .steps-table__title; edit .datatables__row-edit</code></td></tr><tr><td>Detail row</td><td><code>.datatables__row-detail &gt; .step-detail (__media / __chip / __body / __link)</code></td></tr><tr><td>Footer</td><td><code>.datatables__footer / __pagination / __page-btn</code></td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>surfaces</td><td>--ai-datatable-table-bg / -header-bg / -subheader-bg / -footer-bg / -expanded-bg</td></tr><tr><td>icons</td><td>dash --ai-icon-contrast, live tick --ai-text-success</td></tr><tr><td>detail chip</td><td>1px --ai-border-secondary, --ai-radius-sm, --ai-spacing-1 / --ai-spacing-3, --ai-font-fixed-xxs --ai-leading-sm --ai-text-contrast</td></tr><tr><td>detail body</td><td>--ai-font-fixed-xs; p --ai-leading-md --ai-text-secondary; h4 SemiBold --ai-leading-lg --ai-text-primary</td></tr><tr><td>detail indent</td><td>--ai-spacing-9 (checkbox column)</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Built 2026-09-28 from the View &amp; Edit kit (section <code>3861:1902</code>, CC Light mode). The kit was componentised from a code-capture draft that re-tokenise had bound to random / borrowed tokens; the designer ruled &quot;your recommendations are the way to go&quot;, so bindings were normalised to the right semantic tokens in Figma first and this code follows the kit, not the draft.</li><li>Markup comes from <code>src/cc/templates/RecordScreen/record_markup.py</code> — the demo and the templates are generated from the same function, so they cannot drift.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3881-7518" target="_blank" rel="noreferrer">Open in Figma</a></p>',19))])}const x=r(h,[["render",b]]);export{y as __pageData,x as default};
